function renderCityActivities() { const city = cities.find(item => item.id === state.city) || cities[0]; const activities = cityActivities[city.id] || []; let panel = $("cityActivities"); if (!panel) { panel = document.createElement("div"); panel.id = "cityActivities"; panel.className = "city-activities"; $("cityServices").after(panel); } const cards = activities.map(activity => { if (activity.id === "vending") return `<div class="city-activity vending-game"><span><b>${activity.title}</b><small>先投入 ₡25，再取出隨機飲料補品</small><div class="vending-state" id="vendingState">投幣槽：₡0 / 25</div></span><button type="button" class="activity-action" data-vending="coin">投入硬幣</button><button type="button" class="activity-action" data-vending="dispense" disabled>取出飲料</button></div>`; return `<div class="city-activity"><span class="activity-icon">${activity.icon}</span><span><b>${activity.title}</b><small>${activity.desc}</small></span><button type="button" class="activity-action" data-city-activity="${activity.id}">開始</button></div>`; }).join(""); panel.innerHTML = `<div class="activity-heading"><b>${state.language === "en" ? "REPEATABLE CITY ACTIVITIES" : "城市循環活動"}</b><small>${state.language === "en" ? "Play again anytime" : "可不斷重複遊玩"}</small></div>${cards}`; panel.querySelectorAll("[data-city-activity]").forEach(button => button.addEventListener("click", () => useCityActivity(button.dataset.cityActivity))); panel.querySelectorAll("[data-vending]").forEach(button => button.addEventListener("click", () => useVendingMachine(button.dataset.vending))); }
function useVendingMachine(action) { state.vendingCredit = state.vendingCredit || 0; if (action === "coin") { if (state.credits < 25) return toast("Credits 不足"); state.credits -= 25; state.vendingCredit = 25; state.vendingAnimation = "coin"; addFeed("飲料機吞入 ₡25，指示燈開始閃爍。", "warn"); toast("投幣成功 // 請取貨"); } else if (action === "dispense" && state.vendingCredit >= 25) { state.vendingCredit = 0; state.vendingAnimation = "dispense"; const rewards = [{ text: "霓虹能量飲 // RAM +20", apply: () => { state.ram = clamp(state.ram + 20, 0, 100); } }, { text: "冷卻汽水 // HEAT -6", apply: () => { state.heat = clamp(state.heat - 6, 0, 100); } }, { text: "維生果凍 // VITAL +18", apply: () => { state.hp = clamp(state.hp + 18, 0, 100 + (state.upgrades.includes("plating") ? 15 : 0)); } }, { text: "幸運代幣 // ₡45", apply: () => { state.credits += 45; } }]; const reward = rewards[Math.floor(Math.random() * rewards.length)]; reward.apply(); addFeed(`飲料機掉出：${reward.text}。`, "warn"); toast(reward.text); } else return; saveState(); render(); }
function syncVendingControls() { const stateLabel = $("vendingState"); const coin = document.querySelector("[data-vending=coin]"); const dispense = document.querySelector("[data-vending=dispense]"); const machine = document.querySelector(".vending-game"); if (!stateLabel || !coin || !dispense) return; const credit = state.vendingCredit || 0; stateLabel.textContent = `投幣槽：₡${credit} / 25`; coin.disabled = credit >= 25; dispense.disabled = credit < 25; if (machine && state.vendingAnimation) { machine.dataset.animation = state.vendingAnimation; setTimeout(() => { state.vendingAnimation = ""; render(); }, 900); } }
