async function connectFirebase() { try { const response = await fetch("config/firebaseConfig.json"); if (!response.ok) throw new Error(`Firebase config HTTP ${response.status}`); firebaseConfig = await response.json(); const app = initializeApp(firebaseConfig); database = getDatabase(app); auth = getAuth(app); await setPersistence(auth, browserLocalPersistence); onAuthStateChanged(auth, async user => { currentUser = user; if (!user) { $("connection").textContent = "● LOGIN REQUIRED"; $("cloudState").textContent = "○ SIGN IN TO SYNC"; render(); return } $("connection").textContent = "● CLOUD CONNECTED"; $("cloudState").textContent = "● SYNCING"; const snapshot = await get(ref(database, `neonpunk/${user.uid}`)); if (snapshot.exists()) { state = { ...defaultState, ...snapshot.val() }; localStorage.setItem("neonpunk-save", JSON.stringify(state)); } $("loginModal").hidden = true; render(); saveState(); }); } catch (error) { $("connection").textContent = "● FIREBASE ERROR"; $("cloudState").textContent = "○ CHECK CONFIG"; } }
