function decorateInventoryCounts() { document.querySelectorAll("#inventoryActions [data-inventory]").forEach(button => { const count = Math.max(0, Number(state.inventory[button.dataset.inventory]) || 0); let label = button.querySelector(".inventory-label"); if (!label) { label = document.createElement("span"); label.className = "inventory-label"; [...button.childNodes].filter(node => node.nodeType === Node.TEXT_NODE).forEach(node => { label.textContent += node.textContent; node.remove(); }); button.prepend(label); } let node = button.querySelector(".inventory-count"); if (!node) { node = document.createElement("b"); node.className = "inventory-count"; button.appendChild(node); } const text = `×${count}`; if (node.textContent !== text) node.textContent = text; }); }
