	pitFight: [{ title: "鐵籠外的下注單", desc: "擂台還沒開始，但有人願意用一筆小額報酬換你替他改掉一個名字。", twist: "進場押注，讓混亂替你開路。" }],
	memoryDive: [{ title: "孢子裡的第二條街", desc: "記憶網路長出一條你從沒走過的街，盡頭亮著三個入口。", twist: "進入記憶遊戲，可能帶出新的 Combat Action。" }],
	casino: [{ title: "零重力骰室", desc: "骰子停在半空，所有人都在等你先選規則。", twist: "選擇高低、脈衝或記憶牌局。" }],
