function randomStreetEvent(location) { const pool = streetEventPools[location.action] || [{ title: "街角異常", desc: "人群突然向兩側散開，留下短暫而明確的機會。", twist: "你要不要介入？" }]; const event = pool[Math.floor(Math.random() * pool.length)]; return { ...event, locationId: location.id, action: location.action, seed: Math.floor(Math.random() * 9999) }; }
