function resolveStreetAction(action) { state.streetEvent = null; state.streetArcade = null; saveState(); if (action === "arcade" || action === "casino" || action === "memoryDive") return openStreetArcade(); if (action === "signalScan") return openSignalScanner(); if (action === "market") return openOpsDrawer(); if (action === "dungeon") return enterDungeon(state.city); if (action === "vending" || action === "medbay" || action === "salvage" || action === "pitFight" || action === "anomaly" || action === "cool") return useCityActivity(action); }
function openStreetArcade(gameId) { const games = Object.keys(streetArcadeGames); const selected = gameId && streetArcadeGames[gameId] ? gameId : games[Math.floor(Math.random() * games.length)]; const game = streetArcadeGames[selected]; if (state.credits < game.cost) return toast(state.language === "en" ? "INSUFFICIENT CREDITS" : "Credits 不足"); state.credits -= game.cost; state.streetArcade = { id: selected, target: selected === "pulse" ? Math.floor(Math.random() * 3) : selected === "highlow" ? Math.floor(Math.random() * 13) + 1 : Math.floor(Math.random() * 4), startedAt: Date.now() }; saveState(); renderCityExplorer(); }
function resolveStreetArcade(choice) { const round = state.streetArcade; if (!round) return; const game = streetArcadeGames[round.id]; let win = false; let reward = ""; if (round.id === "pulse") win = Number(choice) === round.target; if (round.id === "highlow") win = round.target === 7 ? choice === "mid" : round.target > 7 ? choice === "high" : choice === "low"; if (round.id === "memory") win = Number(choice) === round.target; if (win) { const payout = round.id === "memory" ? 0 : game.cost * (round.id === "pulse" ? 4 + Math.floor(Math.random() * 3) : 5 + Math.floor(Math.random() * 4)); state.credits += payout; state.xp += round.id === "memory" ? 20 : 14; reward = round.id === "memory" ? generateCombatAction().title + " // Combat Action" : `+₡${payout} // +${round.id === "pulse" ? 14 : 18} XP`; } else { state.heat = clamp(state.heat + 3, 0, 100); reward = state.language === "en" ? "MISS // HEAT +3" : "失誤 // HEAT +3"; } state.streetArcade = null; state.streetEvent = null; addFeed(`${game.title} ${win ? "WIN" : "LOSS"}: ${reward}`, win ? "" : "warn"); toast(reward); saveState(); render(); }
function renderStreetArcade(panel) { const round = state.streetArcade; if (!round) return ""; const game = streetArcadeGames[round.id]; const english = state.language === "en"; let choices = []; if (round.id === "pulse") choices = [0, 1, 2].map(value => `<button type="button" class="arcade-choice" data-arcade-choice="${value}"><b>LINE ${value + 1}</b><small>${english ? "PULSE" : "訊號線"}</small></button>`); if (round.id === "highlow") choices = ["low", "mid", "high"].map(value => `<button type="button" class="arcade-choice" data-arcade-choice="${value}"><b>${value.toUpperCase()}</b><small>${value === "low" ? "1-6" : value === "mid" ? "7" : "8-13"}</small></button>`); if (round.id === "memory") choices = [0, 1, 2, 3].map(value => `<button type="button" class="arcade-choice memory-card" data-arcade-choice="${value}"><b>?</b><small>MEMORY ${value + 1}</small></button>`); panel.innerHTML = `<div class="street-arcade"><div class="event-kicker">${english ? "ARCADE // LIVE ROUND" : "娛樂城 // 進行中"}</div><h4>${game.title}</h4><p>${game.desc}</p><div class="arcade-choices">${choices.join("")}</div><button type="button" class="ghost-btn" data-arcade-leave>${english ? "LEAVE TABLE" : "離開牌桌"}</button></div>`; panel.querySelectorAll("[data-arcade-choice]").forEach(button => button.addEventListener("click", () => resolveStreetArcade(button.dataset.arcadeChoice))); panel.querySelector("[data-arcade-leave]")?.addEventListener("click", () => { state.streetArcade = null; saveState(); renderCityExplorer(); }); }
function renderCityExplorerDraft() { const city = cities.find(item => item.id === state.city) || cities[0]; const locations = cityExploreLocations[city.id] || cityExploreLocations.glass; let panel = $("cityExplorer"); const host = $("cityHub"); if (!host) return; if (!panel) { panel = document.createElement("section"); panel.id = "cityExplorer"; panel.className = "city-explorer"; } if (panel.parentElement !== host) host.insertBefore(panel, host.querySelector(".city-tabs") || host.firstChild); const english = state.language === "en"; const active = locations.find(item => item.id === state.cityLocation) || locations[Math.floor(Math.random() * locations.length)]; state.cityLocation = active.id; const event = state.streetEvent || randomStreetEvent(active); state.streetEvent = event; const locationButtons = locations.map(location => `<button type="button" class="explorer-location ${location.id === active.id ? "active" : ""}" data-city-location="${location.id}"><span class="explorer-icon">${location.icon}</span><span><b>${english ? location.nameEn : location.name}</b><small>${english ? location.typeEn : location.type}</small></span><i>›</i></button>`).join(""); if (state.streetArcade) { panel.innerHTML = `<div class="explorer-heading"><div><span class="eyebrow">${english ? "CITY EXPLORATION" : "城市探索"}</span><h3>${english ? "THE STREET IS MOVING" : "街道正在變化"}</h3></div><span class="explorer-route">${city.name}</span></div><div class="explorer-locations">${locationButtons}</div><div class="explorer-scene">${renderStreetArcade(panel)}</div>`; return; } panel.innerHTML = `<div class="explorer-heading"><div><span class="eyebrow">${english ? "CITY EXPLORATION // RANDOM EVENT" : "城市探索 // 隨機事件"}</span><h3>${english ? "CHOOSE A STREET" : "選擇街區，接住事件"}</h3></div><span class="explorer-route">${String(locations.indexOf(active) + 1).padStart(2, "0")} / ${String(locations.length).padStart(2, "0")}</span></div><div class="explorer-locations">${locationButtons}</div><div class="explorer-scene"><span class="scene-kicker">${english ? "STREET EVENT // NEW" : "街角事件 // 新訊號"}</span><h4>${english ? event.title : event.title}</h4><p>${english ? event.desc : event.desc}<br><small>${english ? event.twist : event.twist}</small></p><div class="encounter-choices"><button type="button" class="primary-btn explorer-enter" data-street-action="${event.action}">${english ? "TAKE THE OPENING" : "把握這個機會"} <span>→</span></button><button type="button" class="ghost-btn" data-reroll-street>${english ? "REROLL EVENT" : "重新抽事件"}</button></div><small class="explorer-log">${english ? "Every arrival changes the street." : "每次抵達都會重新改寫街景。"}</small></div>`; panel.querySelectorAll("[data-city-location]").forEach(button => button.addEventListener("click", () => { state.cityLocation = button.dataset.cityLocation; state.streetEvent = randomStreetEvent(locations.find(item => item.id === state.cityLocation)); state.streetArcade = null; saveState(); renderCityExplorer(); })); panel.querySelector("[data-reroll-street]")?.addEventListener("click", () => { state.streetEvent = randomStreetEvent(active); saveState(); renderCityExplorer(); }); panel.querySelector("[data-street-action]")?.addEventListener("click", () => resolveStreetAction(event.action)); }
