function decorateCatalogIcons() { document.querySelectorAll(".loadout-slot-head span").forEach(node => { if (node.querySelector(".catalog-icon")) return; const slot = node.textContent.trim().split(/\s+/).pop(); const item = equipmentCatalog.find(entry => entry.slot === slot); if (item) node.innerHTML = `${catalogIcon(item.id, slot)}<span>${slot}</span>`; }); document.querySelectorAll(".item-icon").forEach(node => { if (node.querySelector(".catalog-icon")) return; const row = node.closest(".market-item, .upgrade-item, .install-record, .combat-action-market"); const title = row?.querySelector("b")?.textContent || ""; const item = [...usableItems, ...allMarketItems, ...upgrades].find(entry => entry.title === title); node.innerHTML = catalogIcon(item?.id || title, ""); }); document.querySelectorAll(".inventory-btn[data-inventory], .consumable-btn[data-combat-consumable]").forEach(button => { if (button.querySelector(".catalog-icon")) return; const id = button.dataset.inventory || button.dataset.combatConsumable; const textNode = [...button.childNodes].find(node => node.nodeType === Node.TEXT_NODE && node.textContent.trim()); if (textNode) textNode.textContent = textNode.textContent.replace(/^\s*[^\s]+\s*/, ""); const icon = document.createElement("span"); icon.className = "catalog-icon-wrap"; icon.innerHTML = catalogIcon(id, ""); button.prepend(icon); }); }
