function openActivityGamble(id) { const panel = $("cityActivities"); if (!panel) return; let game = $("activityGamble"); if (!game) { game = document.createElement("div"); game.id = "activityGamble"; game.className = "dungeon-challenge"; panel.after(game); } const english = state.language === "en"; const isArcade = id === "arcade"; const title = isArcade ? (english ? "UNDERGROUND ARCADE // GUESS THE SIGNAL" : "地下娛樂城 // 猜訊號") : (english ? "MEMORY DIVE // PICK A NODE" : "記憶潛水 // 選擇記憶節點"); const cost = isArcade ? 40 : 70; game.innerHTML = `<div class="activity-heading"><b>${title}</b><small>${english ? `STAKE ₡${cost} // RISK / REWARD` : `下注 ₡${cost} // 高風險高報酬`}</small></div><p>${isArcade ? (english ? "Guess the hidden signal from 1 to 3. Win for a payout; lose the stake." : "猜出 1 到 3 的隱藏訊號。猜中獲得獎勵，猜錯失去下注。") : (english ? "Choose one memory node. Only one contains a Combat Action." : "選擇一個記憶節點，只有一個藏有 Combat Action。")}</p><div class="challenge-options">${[1, 2, 3].map(value => `<button type="button" data-gamble-choice="${value}"><b>${isArcade ? "◈ " + value : ["◌ ALPHA", "◇ BETA", "✦ GAMMA"][value - 1]}</b><small>${isArcade ? (english ? "SIGNAL NODE" : "訊號節點") : (english ? "MEMORY NODE" : "記憶節點")}</small></button>`).join("")}</div>`; game.querySelectorAll("[data-gamble-choice]").forEach(button => button.addEventListener("click", () => resolveActivityGamble(id, Number(button.dataset.gambleChoice)))); game.scrollIntoView({ behavior: "smooth", block: "center" }); }
function resolveActivityGamble(id, choice) { const isArcade = id === "arcade"; const cost = isArcade ? 40 : 70; if (state.credits < cost) return toast("Credits 不足"); state.credits -= cost; const winningChoice = Math.floor(Math.random() * 3) + 1; const win = choice === winningChoice; let reward = ""; if (isArcade && win) { const payout = 80 + Math.floor(Math.random() * 121); state.credits += payout; state.xp += 18; reward = `+₡${payout} // +18 XP`; } else if (!isArcade && win) { const action = generateCombatAction(); reward = `${action.title} // Combat Action`; } else { state.heat = clamp(state.heat + 4, 0, 100); reward = state.language === "en" ? "MISS // STAKE LOST // HEAT +4" : "猜錯 // 下注損失 // HEAT +4"; } $("activityGamble")?.remove(); addFeed(`${isArcade ? "ARCADE" : "MEMORY DIVE"} ${win ? "WIN" : "LOSS"}: ${reward}`, win ? "" : "warn"); toast(reward); saveState(); render(); }
function openSignalScanner() { if (state.combat) return toast("戰鬥中無法掃描訊號"); const modal = $("signalModal"); if (!modal) return; const pools = [{ label: "幽靈頻段", type: "STEALTH", scale: .78, reward: .95, heat: -5 }, { label: "走私頻段", type: "REWARD", scale: 1.08, reward: 1.45, heat: 5 }, { label: "企業黑頻", type: "DANGER", scale: 1.28, reward: 1.8, heat: 13 }, { label: "失真回聲", type: "ANOMALY", scale: .95, reward: 1.15, heat: 2 }, { label: "紅線脈衝", type: "BOUNTY", scale: 1.18, reward: 1.3, heat: 8 }]; signalScanChoices = pools.sort(() => Math.random() - .5).slice(0, 2 + Math.floor(Math.random() * 4)); const positions = [[18, 25], [66, 20], [42, 45], [76, 66], [25, 72]].sort(() => Math.random() - .5); const nodes = $("radarNodes"); if (nodes) nodes.innerHTML = signalScanChoices.map((choice, index) => `<button class="radar-node" data-signal-node="${index}" style="left:${positions[index][0]}%;top:${positions[index][1]}%">?</button>`).join(""); modal.hidden = false; $("signalResults").innerHTML = ""; $("signalScanStatus").textContent = `雷達捕捉到 ${signalScanChoices.length} 個不同頻段。選擇一個接入。`; nodes?.querySelectorAll("[data-signal-node]").forEach(node => node.addEventListener("click", () => resolveSignalNode(Number(node.dataset.signalNode)))); }
function resolveSignalNode(index) { const result = signalScanChoices[index]; if (!result) return; const contract = createSignalContract(); contract.hp = Math.round(contract.hp * result.scale); contract.reward = Math.round(contract.reward * result.reward); contract.title = `${result.label}：${contract.title}`; contract.tag = `SCAN // ${result.type}`; contract.expiresAt = Date.now() + 90000 + Math.floor(Math.random() * 151000); contracts.push(contract); state.contract = contract.id; state.contractExpiresAt = contract.expiresAt; state.heat = clamp(state.heat + result.heat, 0, 100); localStorage.setItem("neonpunk-contracts", JSON.stringify(contracts.filter(item => item.id.startsWith("signal-")))); addFeed(`主動掃描鎖定 ${contract.title}。${result.type} 頻段已接入。`, "warn"); $("signalResults").innerHTML = `<b>${result.label} // ${result.type}</b><span>${contract.enemy} // ${contract.hp} VITAL // ₡${contract.reward}</span><small>訊號有效 ${Math.ceil((contract.expiresAt - Date.now()) / 1000)} 秒，開始潛入後鎖定。</small><button class="primary-btn" id="acceptSignal">接入這份合約</button>`; document.querySelectorAll("[data-signal-node]").forEach(node => { node.disabled = true; node.classList.toggle("revealed", node.dataset.signalNode === String(index)); }); $("acceptSignal").onclick = () => { $("signalModal").hidden = true; render(); toast(`訊號已接入 // ${contract.title}`); }; saveState(); render(); }
